import type { PackageContext } from "../../engine/context.ts";
import { defineStep } from "../../engine/step.ts";

const claudeGitignore =
  "# Generated by pob: do not edit, it is overwritten on each pob run.\n/settings.local.json\n/skills/local.*\n";

interface ClaudeHook {
  type: string;
  command: string;
}

interface ClaudeHookEntry {
  matcher?: string;
  hooks?: ClaudeHook[];
}

const getLintStagedHookCommand = (pkgName: string | undefined): string =>
  pkgName === "pob-monorepo"
    ? "node ./@pob/root/bin/pob-claude-run-lint-staged.js"
    : "./node_modules/.bin/pob-claude-run-lint-staged";

/** Adds the pob hook to the PostToolUse entries, keeping the others. */
export const addPostToolUseHook = (
  postToolUse: readonly ClaudeHookEntry[],
  command: string,
): ClaudeHookEntry[] => {
  const pobEntry = {
    matcher: "Edit|Write|MultiEdit",
    hooks: [{ type: "command", command }],
  };
  const entries = structuredClone([...postToolUse]);
  const existingEntry = entries.find(
    (entry) => entry.matcher === pobEntry.matcher,
  );
  if (!existingEntry) return [...entries, pobEntry];
  for (const hook of pobEntry.hooks) {
    if (!existingEntry.hooks?.some((h) => h.command === hook.command)) {
      (existingEntry.hooks ??= []).push(hook);
    }
  }
  return entries;
};

/** .claude settings of the repository: only at the root. */
export const claudeStep = defineStep<PackageContext>({
  name: "claude",
  reads: ["pkg.name"],
  writes: [
    "claudeSettings.hooks.PostToolUse",
    "files:.claude/.gitignore",
    "files:.claude/settings.json",
  ],
  run: (ctx) => {
    if (!ctx.facts.isRoot) {
      ctx.output.removed(".claude/.gitignore");
      ctx.output.removed(".claude/settings.json");
      return;
    }

    ctx.output.owned(".claude/.gitignore", claudeGitignore);

    const settings = ctx.model("claudeSettings", ".claude/settings.json");
    settings.set(
      "hooks.PostToolUse",
      addPostToolUseHook(
        settings.get<ClaudeHookEntry[]>("hooks.PostToolUse") ?? [],
        getLintStagedHookCommand(ctx.pkg.get<string>("name")),
      ),
    );
    ctx.output.merged(
      ".claude/settings.json",
      settings,
      (model) => JSON.stringify(model.snapshot(), null, 2),
      { format: "oxfmt" },
    );
  },
});
